<style>
#attachment-gallery{width:min(1440px,calc(100vw - 32px));height:min(1100px,calc(100dvh - 32px));max-width:100vw;max-height:100dvh;padding:0;border:1px solid #516259;border-radius:12px;background:#14231e;color:#fff;overflow:hidden}
#attachment-gallery[open]{display:flex;flex-direction:column}#attachment-gallery::backdrop{background:#07130ee8}
.attachment-gallery-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 16px;flex-shrink:0}.attachment-gallery-toolbar h2{font:600 16px/1.4 system-ui;min-width:0;flex:1;margin:0;overflow-wrap:anywhere}.attachment-gallery-toolbar .button{min-height:44px;background:#fff;color:#183c2f;border:1px solid #c7d5c9}.attachment-gallery-toolbar .button:disabled{opacity:.5}.attachment-gallery-toolbar button:focus-visible{outline:3px solid #e5b858;outline-offset:3px}
.attachment-gallery-stage{min-height:0;flex:1;overflow:auto;overscroll-behavior:contain;display:flex;align-items:center;background:#0b1511}.attachment-gallery-stage img{display:block;max-width:100%;max-height:100%;object-fit:contain;margin:auto}.attachment-gallery-stage img[hidden]{display:none}.attachment-gallery-stage img.is-zoomed{max-width:none;max-height:none;flex-shrink:0;align-self:flex-start;margin:0}.attachment-gallery-status{margin:0;padding:0 16px}.attachment-gallery-footer{justify-content:center}.attachment-gallery-footer span{min-width:65px;text-align:center}
.discussion-image{display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:112px;min-height:96px;overflow:hidden;background:#eef3ec;color:#183c2f;border:1px solid var(--line);border-radius:8px;padding:6px;cursor:pointer}.discussion-image img{width:98px;height:68px;object-fit:cover}.discussion-image span{font:600 12px system-ui}.discussion-image:focus-visible{outline:3px solid #b28a3e;outline-offset:3px}
@media(max-width:650px){#attachment-gallery{inset:0;margin:0;width:100vw;height:100dvh;border:0;border-radius:0}.attachment-gallery-toolbar{padding:10px max(12px,env(safe-area-inset-right)) 10px max(12px,env(safe-area-inset-left));gap:6px}.attachment-gallery-toolbar h2{flex-basis:65%}.attachment-gallery-footer{padding-bottom:max(12px,env(safe-area-inset-bottom))}}
</style>
<dialog id="attachment-gallery" aria-labelledby="attachment-gallery-title">
  <header class="attachment-gallery-toolbar"><h2 id="attachment-gallery-title" data-gallery-title>Photo</h2><span data-gallery-count></span><button class="button" type="button" data-gallery-close>Close photo</button></header>
  <p class="attachment-gallery-status" data-gallery-status role="status" aria-live="polite"></p>
  <div class="attachment-gallery-stage" data-gallery-stage><img data-gallery-image alt="" hidden></div>
  <footer class="attachment-gallery-toolbar attachment-gallery-footer" aria-label="Photo controls"><button class="button" type="button" data-gallery-nav data-gallery-prev aria-label="Previous photo">Previous</button><button class="button" type="button" data-gallery-zoom-out aria-label="Zoom out photo">−</button><span data-gallery-zoom-value>100%</span><button class="button" type="button" data-gallery-zoom-in aria-label="Zoom in photo">+</button><button class="button" type="button" data-gallery-fit>Fit</button><button class="button" type="button" data-gallery-nav data-gallery-next aria-label="Next photo">Next</button></footer>
</dialog>
